import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('SingleChildScrollView'),
        ),
        body: SingleChildScrollView(
          // Айналдырылатын аймақтың ішкі шегіністері
          padding: const EdgeInsets.all(16),

          // Айналдыру физикасы (iOS сияқты серпу)
          physics: const BouncingScrollPhysics(),

          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Тақырып
              const Text(
                'Тіркелу формасы',
                style: TextStyle(
                  fontSize: 24,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 20),

              // Форма өрістері
              const TextField(
                decoration: InputDecoration(
                  labelText: 'Аты',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.person),
                ),
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Email',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.email),
                ),
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Телефон',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.phone),
                ),
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Құпия сөз',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.lock),
                ),
                obscureText: true,
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Құпия сөзді қайталаңыз',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.lock_outline),
                ),
                obscureText: true,
              ),
              const SizedBox(height: 16),

              // Сипаттама
              Container(
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.blue.shade50,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: const Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Қолдану шарттары',
                      style: TextStyle(fontWeight: FontWeight.bold),
                    ),
                    SizedBox(height: 8),
                    Text(
                      'Тіркелу арқылы сіз біздің қолдану шарттарымен және құпиялылық саясатымызбен келісесіз. Біз сіздің деректеріңіздің қауіпсіздігін қамтамасыз етеміз.',
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 24),

              // Түйме
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: () {},
                  style: ElevatedButton.styleFrom(
                    padding: const EdgeInsets.all(16),
                  ),
                  child: const Text(
                    'Тіркелу',
                    style: TextStyle(fontSize: 16),
                  ),
                ),
              ),
              const SizedBox(height: 16),

              // Қосымша ақпарат
              const Center(
                child: Text(
                  'Аккаунт бар ма? Кіру',
                  style: TextStyle(color: Colors.blue),
                ),
              ),

              // Айналдыруды көрсету үшін қосымша контент
              const SizedBox(height: 40),
              const Divider(),
              const SizedBox(height: 20),
              const Text(
                'Неге бізді таңдайды?',
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 16),

              // Артықшылықтар
              _buildFeatureCard(
                Icons.speed,
                'Жылдам',
                'Тіркелу бір минуттан аз уақыт алады',
              ),
              _buildFeatureCard(
                Icons.security,
                'Қауіпсіз',
                'Сіздің деректеріңіз сенімді қорғалған',
              ),
              _buildFeatureCard(
                Icons.support_agent,
                '24/7 қолдау',
                'Біз әрқашан көмектесуге дайынбыз',
              ),
            ],
          ),
        ),
      ),
    );
  }

  static Widget _buildFeatureCard(IconData icon, String title, String desc) {
    return Card(
      margin: const EdgeInsets.only(bottom: 12),
      child: ListTile(
        leading: CircleAvatar(
          child: Icon(icon),
        ),
        title: Text(title),
        subtitle: Text(desc),
      ),
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: DefaultTabController(
        length: 3,
        child: Scaffold(
          appBar: AppBar(
            title: const Text('ListView мысалдары'),
            bottom: const TabBar(
              tabs: [
                Tab(text: 'Қарапайым'),
                Tab(text: 'Builder'),
                Tab(text: 'Separated'),
              ],
            ),
          ),
          body: TabBarView(
            children: [
              // 1. Қарапайым ListView
              _buildSimpleListView(),

              // 2. ListView.builder
              _buildListViewBuilder(),

              // 3. ListView.separated
              _buildListViewSeparated(),
            ],
          ),
        ),
      ),
    );
  }

  // Қарапайым ListView - кішкентай тізімдер үшін
  Widget _buildSimpleListView() {
    return ListView(
      padding: const EdgeInsets.all(16),
      children: const [
        Card(
          child: ListTile(
            leading: Icon(Icons.home, color: Colors.blue),
            title: Text('Басты бет'),
            subtitle: Text('Басты экранға оралу'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.person, color: Colors.green),
            title: Text('Профиль'),
            subtitle: Text('Профиль параметрлері'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.settings, color: Colors.orange),
            title: Text('Параметрлер'),
            subtitle: Text('Қосымша параметрлері'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.help, color: Colors.purple),
            title: Text('Көмек'),
            subtitle: Text('Жиі қойылатын сұрақтар'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.info, color: Colors.teal),
            title: Text('Қосымша туралы'),
            subtitle: Text('Нұсқа және ақпарат'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        SizedBox(height: 20),
        Center(
          child: Text(
            'Қарапайым ListView барлық\nэлементтерді бірден жасайды',
            textAlign: TextAlign.center,
            style: TextStyle(color: Colors.grey),
          ),
        ),
      ],
    );
  }

  // ListView.builder - үлкен тізімдер үшін
  Widget _buildListViewBuilder() {
    // Деректерді имитациялау - 100 контакт
    final contacts = List.generate(
      100,
      (index) => {
        'name': 'Контакт ${index + 1}',
        'phone': '+7 ${700 + index} 123 45 67',
        'avatar': Colors.primaries[index % Colors.primaries.length],
      },
    );

    return ListView.builder(
      padding: const EdgeInsets.all(8),
      // Элементтер саны
      itemCount: contacts.length,
      // Элемент жасау функциясы
      itemBuilder: (context, index) {
        final contact = contacts[index];
        return Card(
          child: ListTile(
            leading: CircleAvatar(
              backgroundColor: contact['avatar'] as Color,
              child: Text(
                (contact['name'] as String)[0],
                style: const TextStyle(color: Colors.white),
              ),
            ),
            title: Text(contact['name'] as String),
            subtitle: Text(contact['phone'] as String),
            trailing: IconButton(
              icon: const Icon(Icons.call),
              onPressed: () {},
            ),
          ),
        );
      },
    );
  }

  // ListView.separated - бөлгіштермен
  Widget _buildListViewSeparated() {
    final messages = [
      {'sender': 'Әлия', 'text': 'Сәлем! Қалайсың?', 'time': '10:30'},
      {'sender': 'Мама', 'text': 'Қоңырау шалуды ұмытпа', 'time': '09:15'},
      {'sender': 'Жұмыс', 'text': 'Кездесу сағат 15:00-де', 'time': 'Кеше'},
      {'sender': 'Данияр', 'text': 'Ертең кездесеміз!', 'time': 'Кеше'},
      {'sender': 'Банк', 'text': 'Төлеміңіз өтті', 'time': 'Дс'},
      {'sender': 'Жеткізу', 'text': 'Тапсырыс жеткізілді', 'time': 'Дс'},
      {'sender': 'Асет', 'text': 'Керемет код!', 'time': 'Жс'},
    ];

    return ListView.separated(
      padding: const EdgeInsets.all(8),
      itemCount: messages.length,
      // Элементтер арасындағы бөлгіш
      separatorBuilder: (context, index) => const Divider(
        height: 1,
        indent: 72, // Сол жақтан шегініс (аватар астында)
      ),
      // Тізім элементі
      itemBuilder: (context, index) {
        final msg = messages[index];
        return ListTile(
          leading: CircleAvatar(
            child: Text(msg['sender']![0]),
          ),
          title: Text(msg['sender']!),
          subtitle: Text(
            msg['text']!,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
          trailing: Text(
            msg['time']!,
            style: const TextStyle(
              color: Colors.grey,
              fontSize: 12,
            ),
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

