              SizedBox(
                height: 40,
                child: ListView(
                  scrollDirection: Axis.horizontal,
                  padding: const EdgeInsets.symmetric(horizontal: 8),
                  children: [
                    _buildCategoryChip('Барлығы', true),
                    _buildCategoryChip('Музыка', false),
                    _buildCategoryChip('Ойындар', false),
                    _buildCategoryChip('Жаңалықтар', false),
                    _buildCategoryChip('Спорт', false),
                    _buildCategoryChip('Фильмдер', false),
                    _buildCategoryChip('Білім', false),
