                  const SizedBox(height: 8),
                  Wrap(
                    spacing: 8,
                    children: [
                      _buildPhysicsChip('Bouncing', 'iOS стилі'),
                      _buildPhysicsChip('Clamping', 'Android'),
                      _buildPhysicsChip('Never', 'Өшірулі'),
                      _buildPhysicsChip('Always', 'Әрқашан'),
                    ],
                  ),
                  const SizedBox(height: 8),
                  Text(
                    _getPhysicsDescription(),
                    style: TextStyle(
                      color: Colors.grey.shade600,
                      fontSize: 12,
                    ),
                  ),
                ],
              ),
            ),

            // Таңдалған физикасы бар тізім
            Expanded(
              child: ListView.builder(
                physics: _physics,
                padding: const EdgeInsets.all(8),
                itemCount: 15,
                itemBuilder: (context, index) {
                  return Card(
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: Colors.primaries[index % Colors.primaries.length],
                        child: Text(
                          '${index + 1}',
                          style: const TextStyle(color: Colors.white),
                        ),
                      ),
                      title: Text('Элемент ${index + 1}'),
                      subtitle: Text('$_selectedPhysics тізімін айналдырып көріңіз'),
                      trailing: const Icon(Icons.chevron_right),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildPhysicsChip(String physics, String label) {
    final isSelected = _selectedPhysics == physics;
    return ChoiceChip(
      label: Text(label),
      selected: isSelected,
      onSelected: (selected) {
        if (selected) {
          setState(() => _selectedPhysics = physics);
        }
      },
    );
  }

  String _getPhysicsDescription() {
    switch (_selectedPhysics) {
      case 'Bouncing':
        return '🧊 "Резеңке" эффектісі - контент шеттерде серпіледі (iOS сияқты)';
      case 'Clamping':
        return '🏖️ Контент шеттерде жарқырау эффектісімен тоқтайды (Android сияқты)';
