import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatefulWidget {
  const MyApp({super.key});

  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  // Айналдыру контроллері
  final ScrollController _scrollController = ScrollController();

  // "Жоғары" түймесін көрсету керек пе
  bool _showScrollToTop = false;

  // Көрсету үшін ағымдағы позиция
  double _scrollOffset = 0;

  @override
  void initState() {
    super.initState();

    // Айналдыру өзгерістерін тыңдаймыз
    _scrollController.addListener(_onScroll);
  }

  void _onScroll() {
    setState(() {
      _scrollOffset = _scrollController.offset;
      // 200 пиксельден көп айналдырсақ түймені көрсетеміз
      _showScrollToTop = _scrollController.offset > 200;
    });
  }

  // Басына айналдыру
  void _scrollToTop() {
    _scrollController.animateTo(
      0,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeOut,
    );
  }

  // Соңына айналдыру
  void _scrollToBottom() {
    _scrollController.animateTo(
      _scrollController.position.maxScrollExtent,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeOut,
    );
  }

  // Белгілі бір элементке айналдыру
  void _scrollToItem(int index) {
    // Элементтің шамамен биіктігі = 80
    _scrollController.animateTo(
      index * 80.0,
      duration: const Duration(milliseconds: 300),
      curve: Curves.easeInOut,
    );
  }

  @override
  void dispose() {
    // Ресурстарды босатуды ұмытпаңыз!
    _scrollController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('ScrollController'),
          actions: [
            // Төмен айналдыру түймесі
            IconButton(
              icon: const Icon(Icons.arrow_downward),
              onPressed: _scrollToBottom,
              tooltip: 'Соңына',
            ),
          ],
        ),
        body: Column(
          children: [
            // Ақпарат панелі
            Container(
              padding: const EdgeInsets.all(12),
              color: Colors.blue.shade50,
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        'Позиция: ${_scrollOffset.toStringAsFixed(0)} px',
                        style: const TextStyle(fontWeight: FontWeight.bold),
                      ),
                      Text(
                        'Макс: ${_scrollController.hasClients ? _scrollController.position.maxScrollExtent.toStringAsFixed(0) : "?"} px',
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  // Айналдыру прогресс-бары
                  LinearProgressIndicator(
                    value: _scrollController.hasClients && 
                           _scrollController.position.maxScrollExtent > 0
                        ? _scrollOffset / _scrollController.position.maxScrollExtent
                        : 0,
                    backgroundColor: Colors.grey.shade300,
                  ),
                ],
              ),
            ),

            // Жылдам өтулер
            SizedBox(
              height: 50,
              child: ListView(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
                children: List.generate(
                  10,
                  (index) => Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: ActionChip(
                      label: Text('#${(index + 1) * 5} дейін'),
                      onPressed: () => _scrollToItem((index + 1) * 5 - 1),
                    ),
                  ),
                ),
              ),
            ),

            // Негізгі тізім
            Expanded(
              child: ListView.builder(
                controller: _scrollController, // Контроллерді байланыстырамыз!
                padding: const EdgeInsets.all(8),
                itemCount: 50,
                itemBuilder: (context, index) {
                  return Card(
                    color: index % 5 == 0 
                        ? Colors.blue.shade50 
                        : null,
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: Colors.primaries[index % Colors.primaries.length],
                        child: Text(
                          '${index + 1}',
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 12,
                          ),
                        ),
                      ),
                      title: Text('Элемент ${index + 1}'),
                      subtitle: Text(
                        index % 5 == 0 
                            ? '⭐ Әр 5-ші элемент ерекшеленген'
                            : 'Тізімді айналдырыңыз',
                      ),
                    ),
                  );
                },
              ),
            ),
          ],
        ),

        // "Жоғары" түймесі
        floatingActionButton: AnimatedOpacity(
          opacity: _showScrollToTop ? 1.0 : 0.0,
          duration: const Duration(milliseconds: 200),
          child: FloatingActionButton(
            onPressed: _showScrollToTop ? _scrollToTop : null,
            child: const Icon(Icons.arrow_upward),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(
      home: NewsFeedScreen(),
    );
  }
}

class NewsFeedScreen extends StatefulWidget {
  const NewsFeedScreen({super.key});

  @override
  State<NewsFeedScreen> createState() => _NewsFeedScreenState();
}

class _NewsFeedScreenState extends State<NewsFeedScreen> {
  final ScrollController _scrollController = ScrollController();
  bool _showScrollToTop = false;
  int _selectedCategory = 0;

  // Санаттар
  final List<String> _categories = [
    'Барлығы',
    'Технология',
    'Спорт',
    'Саясат',
    'Экономика',
    'Мәдениет',
    'Ғылым',
  ];

  // Жаңалықтарды имитациялау
  final List<Map<String, dynamic>> _news = List.generate(
    20,
    (index) => {
      'title': 'Жаңалық тақырыбы ${index + 1}: Бүгін маңызды оқиға болды',
      'source': ['Tengrinews', 'Zakon.kz', 'Nur.kz', 'Informburo'][index % 4],
      'time': '${index + 1} сағат бұрын',
      'imageIndex': index,
      'category': index % 7,
    },
  );

  @override
  void initState() {
    super.initState();
    _scrollController.addListener(() {
      setState(() {
        _showScrollToTop = _scrollController.offset > 300;
      });
    });
  }

  @override
  void dispose() {
    _scrollController.dispose();
    super.dispose();
  }

  Future<void> _refresh() async {
    // Жүктеуді имитациялау
    await Future.delayed(const Duration(seconds: 1));
    // Нақты қосымшада серверден деректерді жүктеу
  }

  @override
  Widget build(BuildContext context) {
    // Жаңалықтарды санат бойынша сүзу
    final filteredNews = _selectedCategory == 0
        ? _news
        : _news.where((n) => n['category'] == _selectedCategory).toList();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Жаңалықтар'),
        actions: [
          IconButton(
            icon: const Icon(Icons.search),
            onPressed: () {},
          ),
          IconButton(
            icon: const Icon(Icons.notifications_outlined),
            onPressed: () {},
          ),
        ],
      ),
      body: Column(
        children: [
          // Санаттардың көлденең тізімі
          SizedBox(
            height: 50,
            child: ListView.builder(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
              itemCount: _categories.length,
              itemBuilder: (context, index) {
                final isSelected = _selectedCategory == index;
                return Padding(
                  padding: const EdgeInsets.only(right: 8),
                  child: ChoiceChip(
                    label: Text(_categories[index]),
                    selected: isSelected,
                    onSelected: (selected) {
                      if (selected) {
                        setState(() => _selectedCategory = index);
                      }
                    },
                  ),
                );
              },
            ),
          ),

          // Pull-to-refresh бар жаңалықтардың тік тізімі
          Expanded(
            child: RefreshIndicator(
              onRefresh: _refresh,
              child: ListView.builder(
                controller: _scrollController,
                padding: const EdgeInsets.all(8),
                itemCount: filteredNews.length,
                itemBuilder: (context, index) {
                  final news = filteredNews[index];

                  // Бірінші жаңалық - үлкен карточка
                  if (index == 0) {
                    return _buildFeaturedCard(news);
                  }

                  // Қалғандары - ықшам карточкалар
                  return _buildNewsCard(news);
                },
              ),
            ),
          ),
        ],
      ),

      // "Жоғары" түймесі
      floatingActionButton: _showScrollToTop
          ? FloatingActionButton.small(
              onPressed: () {
                _scrollController.animateTo(
                  0,
                  duration: const Duration(milliseconds: 500),
                  curve: Curves.easeOut,
                );
              },
              child: const Icon(Icons.arrow_upward),
            )
          : null,
    );
  }

  // Басты жаңалық үшін үлкен карточка
  Widget _buildFeaturedCard(Map<String, dynamic> news) {
    return Card(
      clipBehavior: Clip.antiAlias,
      margin: const EdgeInsets.only(bottom: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Үлкен сурет
          Container(
            height: 200,
            width: double.infinity,
            decoration: BoxDecoration(
              image: DecorationImage(
                image: NetworkImage(
                  'https://picsum.photos/400/200?random=${news['imageIndex']}',
                ),
                fit: BoxFit.cover,
              ),
            ),
            child: Container(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [
                    Colors.transparent,
                    Colors.black.withOpacity(0.7),
                  ],
                ),
              ),
              padding: const EdgeInsets.all(16),
              alignment: Alignment.bottomLeft,
              child: Column(
                mainAxisAlignment: MainAxisAlignment.end,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.red,
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: const Text(
                      'Басты',
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    news['title'] as String,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ],
              ),
            ),
          ),
          // Жаңалық туралы ақпарат
          Padding(
            padding: const EdgeInsets.all(12),
            child: Row(
              children: [
                const CircleAvatar(
                  radius: 12,
                  child: Icon(Icons.newspaper, size: 14),
                ),
                const SizedBox(width: 8),
                Text(
                  news['source'] as String,
                  style: const TextStyle(fontWeight: FontWeight.w500),
                ),
                const Spacer(),
                Text(
                  news['time'] as String,
                  style: TextStyle(color: Colors.grey.shade600),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // Қалған жаңалықтар үшін ықшам карточка
  Widget _buildNewsCard(Map<String, dynamic> news) {
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      child: InkWell(
        onTap: () {},
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Жаңалық мәтіні
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      news['title'] as String,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        fontWeight: FontWeight.w500,
                        height: 1.3,
                      ),
                    ),
                    const SizedBox(height: 8),
                    Row(
                      children: [
                        Text(
                          news['source'] as String,
                          style: TextStyle(
                            color: Colors.grey.shade600,
                            fontSize: 12,
                          ),
                        ),
                        const Text(' • '),
                        Text(
                          news['time'] as String,
                          style: TextStyle(
                            color: Colors.grey.shade600,
                            fontSize: 12,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 12),
              // Кішкентай сурет
              ClipRRect(
                borderRadius: BorderRadius.circular(8),
                child: Image.network(
                  'https://picsum.photos/100/80?random=${news['imageIndex']}',
                  width: 100,
                  height: 80,
                  fit: BoxFit.cover,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
